{
  "hallazgos": [
    {
      "clasificacion": "NO_CONFORMIDAD",
      "justificacion": "Se evidencia el incumplimiento de la conservación de información documentada requerida para asegurar la operación y control del servicio de hospitalización, al no encontrarse la valoración de enfermería en 5 de 20 historias clínicas revisadas.",
      "hallazgo_corregido": "Durante la auditoría al proceso de Hospitalización se evidenció que en 5 de 20 historias clínicas revisadas no se encontró registrada la valoración de enfermería requerida, incumpliendo con la conservación de la información documentada necesaria para apoyar la operación y evidenciar que los procesos se realizan según lo planificado, de acuerdo con lo establecido en la NTC-ISO 9001:2015, numeral 4.4.2.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 4.4.2",
      "evidencia": "Ausencia del registro de la valoración de enfermería en 5 de 20 historias clínicas revisadas durante la auditoría.",
      "criterios_citados": [
        {
          "criterio_id": "1d594cb0-5766-4e50-ad2f-48bd61bb6696",
          "numeral": "4.4.2",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de fallas en la continuidad del cuidado o eventos adversos debido a la ausencia del registro de la valoración de enfermería en la historia clínica, lo que podría ocasionar un deterioro de severidad moderada en el estado de salud del paciente.",
        "dimension": "CALIDAD_SEGURIDAD_PACIENTE",
        "probabilidad": 3,
        "impacto": 3,
        "justificacion": "Se estima una probabilidad posible (3) dado que la omisión se detectó en el 25% de la muestra evaluada (5 de 20 casos). El impacto se valora como moderado (3) puesto que la falta de información clínica clave puede derivar en decisiones de cuidado inadecuadas que afecten transitoriamente la salud del paciente hospitalizado."
      },
      "controles": [
        {
          "descripcion": "La Coordinación de Enfermería debe realizar auditorías mensuales de adherencia al diligenciamiento completo y oportuno de la valoración de enfermería en historias clínicas.",
          "tipo": "PREVENTIVO",
          "criterio_id": "1d594cb0-5766-4e50-ad2f-48bd61bb6696"
        },
        {
          "descripcion": "El personal de enfermería responsable de los 5 casos identificados debe revisar y registrar de manera extemporánea o complementaria la valoración del estado de los pacientes, dejando constancia de la trazabilidad y justificación en el sistema clínico.",
          "tipo": "CORRECTIVO",
          "criterio_id": "9f719726-fa7d-4141-ad13-f289ff49f010"
        }
      ],
      "severidad": "media"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "FORTALEZA",
      "justificacion": "El proceso evidencia una práctica sistemática y positiva consistente en el seguimiento periódico a los indicadores y la toma de decisiones basada en datos para definir acciones, lo cual genera un beneficio demostrado para la mejora y la gestión del sistema de calidad.",
      "hallazgo_corregido": "Se evidencia seguimiento mensual a los indicadores por parte del equipo y la utilización sistemática de sus resultados para la definición de acciones, porque favorece la toma de decisiones basada en evidencia y el mejoramiento continuo del proceso.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 9.1.3",
      "evidencia": "Seguimiento mensual documentado a los indicadores y formulación de acciones a partir de los resultados obtenidos.",
      "criterios_citados": [
        {
          "criterio_id": "8d77d1a3-4efb-49a7-a9cb-8274a37c540a",
          "numeral": "9.1.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": null,
      "controles": [],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "OBSERVACION",
      "justificacion": "No se evidencia un incumplimiento directo y demostrable a un requisito mandatorio ya que los registros se encuentran diligenciados y completos, pero la baja legibilidad en algunas firmas constituye una debilidad que representa un riesgo potencial para la trazabilidad y la atribución de responsabilidades.",
      "hallazgo_corregido": "Se evidencia baja legibilidad en algunas de las firmas consignadas en los registros del proceso de Consulta externa, situación que podría dificultar la clara identificación del personal responsable y comprometer la trazabilidad de la atención.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 7.5.3",
      "evidencia": "Registros del proceso completamente diligenciados que presentan algunas firmas con baja legibilidad.",
      "criterios_citados": [
        {
          "criterio_id": "9f719726-fa7d-4141-ad13-f289ff49f010",
          "numeral": "7.5.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de pérdida de trazabilidad en la atención clínica debido a la baja legibilidad en las firmas de los registros, lo que podría dificultar la identificación inequívoca del profesional tratante ante requerimientos asistenciales o legales.",
        "dimension": "PRESTACION_SERVICIO",
        "probabilidad": 3,
        "impacto": 2,
        "justificacion": "Se estima una probabilidad posible (3) al evidenciarse en varios registros evaluados durante la auditoría. El impacto se califica como menor (2), dado que los registros se encuentran completos y la afectación generaría eventuales reprocesos de validación interna sin suspender ni comprometer directamente la prestación del servicio."
      },
      "controles": [
        {
          "descripcion": "La coordinación de Consulta externa debe socializar con el equipo de salud la directriz sobre el registro claro de firmas acompañado de sello, código o posfirma legible en los formatos asistenciales.",
          "tipo": "PREVENTIVO",
          "criterio_id": "9f719726-fa7d-4141-ad13-f289ff49f010"
        },
        {
          "descripcion": "El líder del proceso de Consulta externa debe realizar auditorías mensuales de adherencia al diligenciamiento y preservación de la legibilidad de la información documentada.",
          "tipo": "PREVENTIVO",
          "criterio_id": "9f719726-fa7d-4141-ad13-f289ff49f010"
        }
      ],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "OPORTUNIDAD_DE_MEJORA",
      "justificacion": "El proceso cumple con el registro adecuado de asistencia en medio físico y no presenta incumplimientos normativos ni debilidades críticas, pero existe la posibilidad de optimizar la gestión mediante su digitalización.",
      "hallazgo_corregido": "El proceso de registro de asistencia es susceptible de mejorar mediante la adopción de herramientas digitales o sistematizadas para su diligenciamiento, lo cual permitirá agilizar la consolidación de la información, fortalecer la trazabilidad y optimizar los tiempos de análisis del proceso de Gestión humana.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 7.5.3",
      "evidencia": "El registro de asistencia se realiza de manera conforme y controlada a través de formato físico.",
      "criterios_citados": [
        {
          "criterio_id": "9f719726-fa7d-4141-ad13-f289ff49f010",
          "numeral": "7.5.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de reprocesos o demoras en la consolidación de datos debido al diligenciamiento exclusivamente manual en papel, lo que podría generar demoras en los análisis y reportes del proceso.",
        "dimension": "PRESTACION_SERVICIO",
        "probabilidad": 2,
        "impacto": 1,
        "justificacion": "Dado que el registro se efectúa correctamente, demoras sustanciales son poco frecuentes (improbable), y la persistencia del medio físico no compromete la atención ni afecta la prestación del servicio asistencial (insignificante)."
      },
      "controles": [
        {
          "descripcion": "Evaluar e implementar un mecanismo digitalizado para la captura y consolidación de la asistencia en las actividades de Gestión humana por parte de la coordinación del área.",
          "tipo": "PREVENTIVO",
          "criterio_id": "9f719726-fa7d-4141-ad13-f289ff49f010"
        }
      ],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "NO_CONFORMIDAD",
      "justificacion": "Se evidencia el incumplimiento de un requisito explícito y obligatorio de la norma NTC-ISO 9001:2015, numeral 9.3.3 literal a), el cual exige que las salidas de la revisión por la dirección incluyan decisiones y acciones relacionadas con las oportunidades de mejora.",
      "hallazgo_corregido": "Durante la revisión del informe de la revisión por la dirección se evidenció que no se incluyeron las decisiones y acciones frente a las oportunidades de mejora, incumpliendo lo establecido en la NTC-ISO 9001:2015, numeral 9.3.3 literal a).",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 9.3.3 literal a)",
      "evidencia": "Ausencia de registro de decisiones y acciones relacionadas con las oportunidades de mejora dentro de las salidas de la revisión por la dirección.",
      "criterios_citados": [
        {
          "criterio_id": "08fec393-24ed-450f-bb4a-91b2326d344d",
          "numeral": "9.3.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de estancamiento o pérdida de eficacia del sistema de gestión de la calidad debido a la omisión de decisiones y acciones estratégicas sobre las oportunidades de mejora en la revisión por la dirección, lo que podría generar reprocesos e ineficiencias en la gestión institucional.",
        "dimension": "PRESTACION_SERVICIO",
        "probabilidad": 2,
        "impacto": 2,
        "justificacion": "La revisión por la dirección se ejecuta habitualmente de manera anual o periódica, haciendo que el evento sea poco frecuente (Improbable = 2). La falta de definición de estas decisiones puede ocasionar reprocesos en la gestión gerencial sin suspender la prestación directa de servicios de salud (Menor = 2)."
      },
      "controles": [
        {
          "descripcion": "La Gerencia y el área de Gestión de Calidad deben actualizar el acta o informe de la revisión por la dirección incorporando formalmente las decisiones y acciones tomadas frente a las oportunidades de mejora identificadas.",
          "tipo": "CORRECTIVO",
          "criterio_id": "08fec393-24ed-450f-bb4a-91b2326d344d"
        },
        {
          "descripcion": "El área de Gestión de Calidad debe implementar una lista de verificación previa al cierre de cada revisión por la dirección que valide la inclusión de todas las salidas obligatorias del estándar.",
          "tipo": "PREVENTIVO",
          "criterio_id": "08fec393-24ed-450f-bb4a-91b2326d344d"
        }
      ],
      "severidad": "media"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "OPORTUNIDAD_DE_MEJORA",
      "justificacion": "No se evidencia incumplimiento de un requisito normativo o legal obligatorio aplicable a la capacidad del parqueadero, pero existe una oportunidad para optimizar la capacidad y gestión del espacio físico en beneficio de los usuarios.",
      "hallazgo_corregido": "La capacidad y disponibilidad del parqueadero de visitantes es susceptible de mejorar mediante la evaluación de alternativas de ampliación, redistribución o convenios externos para días de alta afluencia, lo cual permitirá facilitar el acceso y mejorar la comodidad de los usuarios.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 7.1.3",
      "evidencia": "Durante la auditoría se constató que el parqueadero destinado para visitantes cuenta con una capacidad reducida y alcanza su ocupación máxima los días viernes.",
      "criterios_citados": [
        {
          "criterio_id": "7b0d84dc-980a-4200-88f3-eee8adba1b53",
          "numeral": "7.1.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de inconformidad o congestión vehicular en el acceso debido a la capacidad limitada del parqueadero de visitantes los días viernes, lo que podría afectar la percepción de satisfacción y la imagen institucional.",
        "dimension": "REPUTACIONAL",
        "probabilidad": 4,
        "impacto": 1,
        "justificacion": "La saturación se presenta de forma recurrente semanalmente (probable), pero su impacto en la imagen hospitalaria es mínimo e insignificante al tratarse de un servicio complementario."
      },
      "controles": [
        {
          "descripcion": "El área de Gestión de recursos físicos realizará un estudio de capacidad y rotación vehicular para implementar planes de contingencia o convenios de parqueo en días de alta demanda.",
          "tipo": "PREVENTIVO",
          "criterio_id": "7b0d84dc-980a-4200-88f3-eee8adba1b53"
        }
      ],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "NO_CONFORMIDAD",
      "justificacion": "Existe evidencia objetiva de un incumplimiento en los controles de infraestructura y equipos para la atención en el servicio de urgencias, al encontrarse un equipo de control de incendios vencido.",
      "hallazgo_corregido": "Durante la inspección realizada en el área de Urgencias se evidenció un extintor con la fecha de mantenimiento y recarga vencida, incumpliendo lo establecido en la NTC-ISO 9001:2015, numeral 8.5.1, literal d.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 8.5.1, literal d",
      "evidencia": "Extintor ubicado en el área de urgencias con fecha de vencimiento expirada.",
      "criterios_citados": [
        {
          "criterio_id": "7c03ec48-9705-4ff7-8d6a-8671e4ad26f4",
          "numeral": "8.5.1",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de inoperatividad de los equipos de extinción de incendios debido a la falta de mantenimiento y recarga oportuna del extintor, lo que podría comprometer la seguridad de los pacientes y colaboradores ante una emergencia de conato de incendio.",
        "dimension": "CALIDAD_SEGURIDAD_PACIENTE",
        "probabilidad": 3,
        "impacto": 4,
        "justificacion": "El vencimiento del extintor en un área crítica como urgencias genera un riesgo directo sobre la seguridad de pacientes y personal ante un evento de fuego; la probabilidad es posible por falta de seguimiento en las fechas de recarga."
      },
      "controles": [
        {
          "descripcion": "Realizar la recarga y sustitución inmediata del extintor vencido en el área de urgencias.",
          "tipo": "CORRECTIVO",
          "criterio_id": "7c03ec48-9705-4ff7-8d6a-8671e4ad26f4"
        },
        {
          "descripcion": "Establecer un programa periódico de inspección y cronograma de mantenimiento de extintores y equipos de emergencia a cargo del área de SST.",
          "tipo": "PREVENTIVO",
          "criterio_id": "7c03ec48-9705-4ff7-8d6a-8671e4ad26f4"
        }
      ],
      "severidad": "alta"
    },
    {
      "clasificacion": "FORTALEZA",
      "justificacion": "Se identifica una práctica positiva destacada en el personal de urgencias sobre el dominio del protocolo de código azul, lo que genera un beneficio directo en la seguridad y atención del paciente crítico.",
      "hallazgo_corregido": "Se evidencia en el personal del área de Urgencias un elevado nivel de competencia y dominio del protocolo de Código Azul, favoreciendo la oportunidad de la respuesta médica y el fortalecimiento de la seguridad del paciente ante emergencias vitales.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 7.2",
      "evidencia": "Demostración de excelente dominio práctico y teórico del protocolo de código azul por parte del personal del área de urgencias.",
      "criterios_citados": [
        {
          "criterio_id": "eb145164-5acd-42a9-b77a-fed8494baaf5",
          "numeral": "7.2",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": null,
      "controles": [],
      "severidad": "baja"
    }
  ]
}
